function login(k) {
	if (k == undefined) return true;
	name = result["用户名"];
	word = result["密码"];
	inv = result["邀请码"];
	if(k){
 let url="https://freenovel.sbs/api/auth/login";
	body = `{"email":"${name}","password":"${word}","invitationCode":"${inv}"}`
	post = JSON.stringify({
        "body": String(body),
        "method": "POST"
    });
    url+=','+post;
    result = java.ajax(url);
    if(result.match(/\d+/)){
    	java.toast(`\n${name}`+'\n登录成功')
    java.log(result)
    source.setVariable(result)
				} else {
	java.toast("\n请填写登录数据\n点击上方√后重新点击登录按钮");
	}
}}
function D(){
    source.setVariable("")
    java.toast('登出成功')
	}

